const Logo=()=> <Link href="/" className="brand" aria-label="VIBE início"><span className="brand-mark"/>vibe<small>eventos</small></Link>;
function Picker({value,onChange,items,label,cls=''}:{value:string;onChange:(v:string)=>void;items:{value:string;label:string}[];label:string;cls?:string}){return <Select value={value} onValueChange={onChange}><SelectTrigger className={cls||'w-full'} aria-label={label}><SelectValue placeholder={label}/></SelectTrigger><SelectContent>{items.map(i=><SelectItem key={i.value} value={i.value}>{i.label}</SelectItem>)}</SelectContent></Select>}
