const BtnLink=({href,children,kind='primary'}:{href:string;children:ReactNode;kind?:string})=><Link className={'btn '+kind} href={href}>{children}</Link>;
export default function Viva(){
 const path=usePathname()||'/';const router=useRouter();const [mobile,setMobile]=useState(false),[state,setState]=useState<Workspace>(initialWorkspace),[revision,setRevision]=useState(0),[loading,setLoading]=useState(true),[error,setError]=useState(''),[connected,setConnected]=useState(false),[busy,setBusy]=useState(false);
 const refresh=useCallback(async()=>{setLoading(true);try{const r=await fetch('/api/workspace');const j:any=await r.json();if(r.ok){setState(j.state);setRevision(j.revision);setConnected(true);setError('')}else{setConnected(false);if(!j.preview)setError(j.error)}}catch{setError('Não foi possível carregar os dados. Recarregue para tentar novamente.')}finally{setLoading(false)}},[]);
 useEffect(()=>{refresh()},[refresh]);useEffect(()=>{setMobile(false)},[path]);
 async function mutate(action:string,payload:unknown){setBusy(true);try{const r=await fetch('/api/workspace',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,payload,revision})});const j:any=await r.json();if(!r.ok)throw new Error(j.error||'Não foi possível salvar.');setState(j.state);setRevision(j.revision);setConnected(true);return j.state as Workspace}catch(e){toast.error((e as Error).message);return null}finally{setBusy(false)}}
 useEffect(()=>{const context=(document as any).modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();try{Promise.resolve(context.registerTool({name:'search_events',title:'Buscar corridas',description:'Consulta os eventos ilustrativos disponíveis nesta prévia. Não efetua compras.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true},execute:(input:unknown)=>{if(!input||typeof (input as any).query!=='string')throw new Error('Consulta inválida');const q=(input as any).query.toLowerCase();return events.filter(e=>(e.name+' '+e.city).toLowerCase().includes(q)).map(e=>({id:e.id,name:e.name,city:e.city,date:e.date,distances:e.distances,url:'/evento/'+e.id}))}},{signal:lifecycle.signal})).catch(()=>{})}catch{}return()=>lifecycle.abort()},[]);
 const event=events.find(e=>e.id===path.split('/')[2]);
 return <><header className="topbar"><div className="wrap nav-inner"><Logo/><nav className="desktop-links" aria-label="Navegação principal"><Link className={path==='/'?'active':''} href="/">Explorar eventos</Link><Link className={path==='/atleta'?'active':''} href="/atleta">Minha jornada</Link><Link className={path==='/ingressos'?'active':''} href="/ingressos">Minhas inscrições</Link><Link className={path==='/telas'?'active':''} href="/telas">Ver todas as telas</Link></nav><div className="nav-actions"><Link className="btn text desktop-only" href="/gestao">Área do organizador</Link><Link className="btn primary" href="/atleta"><UserRound size={16}/> Minha conta</Link><button className="icon-btn mobile-menu" aria-label="Abrir menu" onClick={()=>setMobile(true)}><Menu size={23}/></button></div></div></header><div className="demo-line">PRÉVIA PRIVADA · Eventos e pedidos de demonstração · Sem cobranças reais</div><Sheet open={mobile} onOpenChange={setMobile}><SheetContent className="mobile-sheet"><SheetTitle className="p-6">Explore a VIVA</SheetTitle><nav><Link href="/">Explorar eventos</Link><Link href="/telas">Ver todas as telas</Link><Link href="/atleta">Minha jornada</Link><Link href="/ingressos">Minhas inscrições</Link><Link href="/gestao">Organizador</Link><Link href="/loja">Lojista</Link><Link href="/admin">Administração do SaaS</Link></nav></SheetContent></Sheet>
 {error&&<div className="wrap"><div className="error row between" style={{marginTop:18}}>{error}<button onClick={refresh}>Tentar novamente</button></div></div>}
 {path==='/'?<Explore state={state} mutate={mutate}/>:path==='/telas'?<AllScreens/>:path.startsWith('/evento/')&&event?<EventDetail event={event} settings={state.settings}/>:path.startsWith('/inscricao/')&&event?<Checkout event={event} state={state} mutate={mutate} busy={busy} connected={connected}/>:path==='/atleta'?<AthleteDashboard state={state} mutate={mutate} busy={busy} loading={loading}/>:path==='/ingressos'?<Tickets state={state} mutate={mutate} busy={busy}/>:['/gestao','/loja','/admin'].some(p=>path.startsWith(p))?<Management path={path} state={state} mutate={mutate} busy={busy}/>:<main className="wrap page-pad"><Empty title="Página não encontrada" text="Volte aos eventos e encontre sua próxima experiência."><BtnLink href="/">Explorar eventos</BtnLink></Empty></main>}
 <footer className="footer"><div className="wrap"><Logo/><p>Experiências que ficam com você.</p><div className="footer-links"><Link href="/gestao">Organizador</Link><Link href="/loja">Lojista</Link><Link href="/admin">SaaS</Link><button onClick={()=>toast.info('Prévia de produto. A política completa de privacidade e os contratos serão configurados antes da abertura das vendas.')} style={{border:0,background:'none',padding:0,fontSize:12}}>Privacidade e termos</button></div></div></footer><Toaster richColors position="top-center"/></>;
}
type Mutation=(a:string,p:unknown)=>Promise<Workspace|null>;
function AllScreens(){
 const sections=[
  {title:'Para quem vai correr',items:[['Vitrine de eventos','/','Buscar corridas e filtrar por distância.'],['Página da corrida','/evento/orla','Ver percurso, distâncias, kit e condições.'],['Inscrição','/inscricao/orla','Escolher atletas e camisetas, conferir ofertas e simular o pagamento.'],['Minha jornada','/atleta','Acompanhar tempos, gráfico e histórico de provas.'],['Minhas inscrições','/ingressos','Consultar pedidos de demonstração e seus códigos de retirada.']]},
  {title:'Organizador do evento',items:[['Visão geral','/gestao','Resumo da corrida e inscrições.'],['Dados do evento','/gestao/evento','Cadastro e descrição da prova.'],['Lotes e distâncias','/gestao/lotes','Preços, quantidades e prorrogação.'],['Camisetas e estoque','/gestao/camisetas','Tamanhos por distância.'],['Kit da corrida','/gestao/kit','Itens entregues aos atletas.'],['Lojas parceiras','/gestao/lojas','Autorização das ofertas.'],['Inscrições','/gestao/pedidos','Acompanhar os pedidos.'],['Entregas','/gestao/entregas','Conferir os códigos dos atletas.'],['Financeiro','/gestao/financeiro','Visualizar taxas e condições.'],['Configurações','/gestao/configuracoes','Ver as regras do evento e das lojas.'],['Equipe','/gestao/equipe','Preparar acessos da equipe.']]},
  {title:'Dono da lojinha',items:[['Visão geral','/loja','Acompanhar ofertas e vendas.'],['Produtos e ofertas','/loja/produtos','Preços especiais, posteriores e estoque.'],['Pedidos','/loja/pedidos','Ver compras dos produtos.'],['Entregas','/loja/entregas','Conferir retirada na loja.'],['Financeiro','/loja/financeiro','Ver custos e repasse estimado.'],['Dados da loja','/loja/configuracoes','Informar endereço e horários.']]},
  {title:'Dono da plataforma',items:[['Visão geral','/admin','Acompanhar a plataforma.'],['Eventos','/admin/eventos','Veja as provas e abra a vitrine.'],['Parceiros','/admin/parceiros','Organizadores e lojas autorizados.'],['Financeiro','/admin/financeiro','Configurar taxas negociadas.'],['Configurações','/admin/configuracoes','Ver setup e aluguel das lojas.'],['Convites e acessos','/admin/equipe','Preparar o cadastro dos parceiros.']]}
 ];
 return <main className="wrap page-pad screens-page"><div className="title-row"><div><span className="eyebrow">Explore a prévia</span><h1>Todas as telas da VIBE</h1><p>Clique em qualquer tela para navegar. Os eventos, pedidos e valores aqui são demonstrativos.</p></div></div>{sections.map(group=><section key={group.title} className="screens-group"><h2>{group.title}</h2><div className="screens-grid">{group.items.map(([name,href,description])=><Link key={href} href={href} className="screen-card"><span><strong>{name}</strong><small>{description}</small></span><ArrowRight size={19} aria-hidden="true"/></Link>)}</div></section>)}</main>;
}
function Explore({state,mutate}:{state:Workspace;mutate:Mutation}){
 const [query,setQuery]=useState(''),[search,setSearch]=useState(''),[city,setCity]=useState('all'),[month,setMonth]=useState('all'),[distance,setDistance]=useState('all');
 const filtered=events.filter(e=>(e.name+' '+e.city).toLocaleLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(search.toLocaleLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,''))&&(city==='all'||e.id===city)&&(month==='all'||e.date.slice(5,7)===month)&&(distance==='all'||e.distances.includes(Number(distance))));
 function run(e:FormEvent){e.preventDefault();setSearch(query);document.getElementById('eventos')?.scrollIntoView({behavior:'smooth',block:'start'})}
 return <main className="wrap"><section className="hero"><img src="/images/orla.jpg" alt="Corredores em uma prova de rua, fotografia ilustrativa"/><div className="hero-shade"/><div className="hero-content"><div className="eyebrow"><Footprints size={15}/> Encontre sua próxima largada</div><h1>O próximo momento<br/>é <span>seu.</span></h1><p>Novos percursos, novas conquistas. Encontre a corrida que vai fazer parte da sua história.</p><a href="#eventos" className="btn green">Explorar corridas <ArrowRight size={16}/></a></div><div className="hero-note"><strong>Cada quilômetro, uma nova história.</strong>Da primeira largada ao seu próximo recorde.</div><div className="hero-bottom" aria-hidden="true"><i/><i/><i/></div></section><form className="search-panel" onSubmit={run}><div className="search-field"><Search/><div><label htmlFor="event-search">Qual será sua próxima experiência?</label><input id="event-search" placeholder="Busque por evento ou cidade" value={query} onChange={e=>setQuery(e.target.value)}/></div></div><div className="search-field"><MapPin/><div><label>Localização</label><Picker cls="filter-select" label="Cidade" value={city} onChange={setCity} items={[{value:'all',label:'Todas as cidades'},...events.map(e=>({value:e.id,label:e.city}))]}/></div></div><div className="search-field"><CalendarDays/><div><label>Quando</label><Picker cls="filter-select" label="Mês" value={month} onChange={setMonth} items={[{value:'all',label:'Qualquer data'},{value:'11',label:'Novembro 2026'},{value:'12',label:'Dezembro 2026'}]}/></div></div><button className="btn primary" type="submit">Encontrar eventos <Search size={16}/></button></form><section id="eventos" style={{scrollMarginTop:25}}><div className="section-head"><div><h2>Sua próxima linha de chegada</h2><p>Escolha seu desafio. A gente cuida da inscrição.</p></div><div className="chips" aria-label="Distâncias">{['all','5','7','10','15','21','42'].map(d=><button key={d} className={'chip '+(distance===d?'selected':'')} onClick={()=>setDistance(d)}>{d==='all'?'Todas':d+' km'}</button>)}</div></div>{filtered.length?<div className="event-grid">{filtered.map(e=><article key={e.id} className="event-card"><Link href={'/evento/'+e.id}><div className="event-cover"><img src={e.image} alt={'Imagem ilustrativa de '+e.name}/><span className="tag">{e.tag}</span></div></Link><button className="favorite" aria-label={(state.favorites.includes(e.id)?'Remover':'Salvar')+' '+e.name} onClick={()=>mutate('favorite',{id:e.id})}><Heart size={16} fill={state.favorites.includes(e.id)?'#16866a':'none'}/></button><Link href={'/evento/'+e.id}><div className="event-info"><div className="event-date">{e.day} {e.month} 2026 · DOMINGO</div><h3>{e.name}</h3><div className="meta"><MapPin size={13}/>{e.city}</div><div className="distances">{e.distances.map(d=><span key={d}>{d} KM</span>)}</div><div className="price-row"><div><small>A partir de, com taxa Pix</small><strong>{money(e.base+feeFor(e.base,'pix',state.settings))}</strong></div><span className="arrow"><ArrowRight size={17}/></span></div></div></Link></article>)}</div>:<Empty title="Nenhuma corrida com esses filtros" text="Tente outra distância, cidade ou período."><button className="btn outline" onClick={()=>{setSearch('');setQuery('');setCity('all');setMonth('all');setDistance('all')}}>Limpar filtros</button></Empty>}</section><div className="athlete-banner"><div className="banner-icon"><TrendingUp size={30}/></div><div style={{flex:1}}><h3>A corrida termina. Sua evolução continua.</h3><p>Reúna seus tempos, acompanhe seus recordes e descubra o quanto você já avançou.</p></div><BtnLink kind="outline" href="/atleta">Conhecer minha jornada <ArrowRight size={17}/></BtnLink></div></main>
}
function EventDetail({event:e,settings}:{event:RaceEvent;settings:Settings}){const [d,setD]=useState(String(e.distances[0]));const price=racePrice(e,Number(d));return <main className="wrap page-pad"><div className="crumb"><Link href="/">Eventos</Link><ChevronRight size={14}/>Corridas<ChevronRight size={14}/>{e.name}</div><img className="detail-cover" src={e.image} alt="Corrida de rua, imagem ilustrativa"/><div className="detail-grid"><div className="detail-main"><span className="tag">Corrida de rua · Evento ilustrativo</span><h1>{e.name}</h1><div className="detail-meta"><span className="meta"><CalendarDays size={17}/>{dateLabel(e.date)}</span><span className="meta"><Clock size={17}/>{e.time}</span><span className="meta"><MapPin size={17}/>{e.city}</span></div><div className="detail-section"><h2>Seu próximo desafio começa aqui</h2><p>{e.description}</p></div><div className="detail-section"><h2>Uma distância para a sua jornada</h2><div className="kit-list">{e.distances.map(d=><div key={d} className="kit-item"><Footprints size={21}/><div><strong>{d} quilômetros</strong><p>{money(racePrice(e,d))} + taxa</p></div></div>)}</div></div><div className="detail-section"><h2>O que vem no seu kit</h2><p>A camiseta é específica para a distância escolhida. Você seleciona o tamanho disponível na inscrição.</p><div className="kit-list">{[[Shirt,'Camiseta da modalidade'],[Ticket,'Número de peito'],[Activity,'Chip de cronometragem'],[Trophy,'Medalha após a conclusão'],[Package,'Sacochila do evento']].map(([I,t]:any)=><div className="kit-item" key={t}><I size={21}/>{t}</div>)}</div></div><div className="detail-section"><h2>Retirada e informações importantes</h2><p>Retirada do kit na véspera, das 10h às 18h, no ponto de atendimento em {e.place}. A camiseta fica reservada para retirada até 30 dias após a prova. Os demais itens seguem o horário de retirada do evento.</p><p style={{marginTop:12}}>Transferência de titularidade até 24 horas antes do evento. Não há troca automática de distância ou camiseta; solicitações excepcionais passam pela organização.</p></div><div className="detail-section"><h2>Cancelamento</h2><p>As compras online seguem o Código de Defesa do Consumidor. A solicitação fica disponível no pedido, respeitando o direito de arrependimento e as demais hipóteses legais. O prazo para transferir a inscrição não limita o direito de cancelamento.</p></div></div><aside className="panel booking-box"><span className="eyebrow">Sua próxima largada</span><h3>Escolha sua distância</h3><Picker label="Distância" value={d} onChange={setD} items={e.distances.map(d=>({value:String(d),label:d+' km'}))}/><p className="muted" style={{marginTop:22}}>1º lote · inscrição</p><div className="big-price">{money(price)}</div><p className="small muted">+ {money(feeFor(price,'pix',settings))} de taxa no Pix</p><div className="rule"/><div className="summary-line"><span>Total no Pix</span><strong>{money(price+feeFor(price,'pix',settings))}</strong></div><Link href={'/inscricao/'+e.id+'?distancia='+d} className="btn primary full" style={{marginTop:12}}>Escolher camiseta <ArrowRight size={16}/></Link><p className="small muted" style={{textAlign:'center',marginTop:14}}>Demonstração · sem pagamento real</p><div className="rule"/><div className="row muted"><ShieldCheck size={20}/>Dados e valores conferidos antes de finalizar.</div></aside></div></main>}
function Checkout({event:e,state,mutate,busy,connected}:{event:RaceEvent;state:Workspace;mutate:Mutation;busy:boolean;connected:boolean}){
 const router=useRouter();const [step,setStep]=useState(0),[athletes,setAthletes]=useState<Athlete[]>([{name:'',email:'',distance:e.distances[0],size:''}]),[ids,setIds]=useState<string[]>([]),[payment,setPayment]=useState('pix'),[terms,setTerms]=useState(false),[parcels,setParcels]=useState('2'),[success,setSuccess]=useState(false);
 useEffect(()=>{const d=Number(new URLSearchParams(window.location.search).get('distancia'));if(e.distances.includes(d))setAthletes(a=>[{...a[0],distance:d}])},[e.id]);
 const base=athletes.reduce((s,a)=>s+racePrice(e,a.distance),0),fee=athletes.reduce((s,a)=>s+feeFor(racePrice(e,a.distance),payment,state.settings),0),extra=ids.reduce((s,id)=>s+products.find(p=>p.id===id)!.price,0),total=base+fee+extra;
 function edit(i:number,key:string,v:string|number){setAthletes(a=>a.map((x,n)=>n===i?{...x,[key]:v,...(key==='distance'?{size:''}:{})}:x))}
 async function finish(){if(!terms){toast.error('Confirme que leu as condições.');return}const r=await mutate('order',{eventId:e.id,athletes,productIds:ids,payment});if(r)setSuccess(true)}
 if(success)return <main className="wrap page-pad"><div className="panel" style={{maxWidth:600,margin:'35px auto',textAlign:'center',padding:45}}><CheckCircle2 size={50} color="#258969" style={{margin:'0 auto 20px'}}/><h1 style={{fontSize:30}}>Sua simulação está pronta</h1><p style={{margin:'18px 0 28px'}}>Nenhum valor foi cobrado. O pedido demonstrativo foi salvo para você testar a experiência de retirada e acompanhar a inscrição.</p><BtnLink href="/ingressos">Ver minhas inscrições <ArrowRight size={17}/></BtnLink></div></main>;
 return <main className="wrap page-pad"><Link href={'/evento/'+e.id} className="crumb"><ArrowLeft size={15}/>Voltar para a corrida</Link><div className="title-row"><div><h1 style={{fontSize:34}}>Sua próxima conquista</h1><p>{e.name} · {dateLabel(e.date)}</p></div><span className="tag">Simulação de inscrição</span></div><div className="stepper">{['Participantes','Ofertas das lojas','Pagamento'].map((s,i)=><div key={s} className={'step '+(i===step?'active':'')}><b>{i<step?<Check size={13}/>:i+1}</b>{s}</div>)}</div><div className="checkout-layout"><div className="stack">{step===0?<form className="stack" onSubmit={ev=>{ev.preventDefault();if(athletes.some(a=>!a.size)){toast.error('Escolha a camiseta de cada participante.');return}setStep(1)}}>{athletes.map((a,i)=><div className="panel" key={i}><div className="row between" style={{marginBottom:20}}><h3 style={{margin:0}}>Atleta {i+1}</h3>{i>0&&<button type="button" aria-label="Remover atleta" className="icon-btn" onClick={()=>setAthletes(x=>x.filter((_,n)=>n!==i))}><X size={17}/></button>}</div><div className="form-grid"><Field label="Nome completo"><input required maxLength={100} value={a.name} onChange={ev=>edit(i,'name',ev.target.value)} placeholder="Nome do participante"/></Field><Field label="E-mail do atleta"><input required type="email" value={a.email} onChange={ev=>edit(i,'email',ev.target.value)} placeholder="atleta@email.com"/></Field><div className="field">Distância<Picker value={String(a.distance)} label={'Distância atleta '+(i+1)} onChange={v=>edit(i,'distance',Number(v))} items={e.distances.map(d=>({value:String(d),label:d+' km · '+money(racePrice(e,d))}))}/></div><div className="field">Camiseta da prova de {a.distance} km<RadioGroup value={a.size} onValueChange={v=>edit(i,'size',v)} className="choice-row">{['PP','P','M','G','GG','XGG'].map(s=><label key={s} className={'choice '+(a.size===s?'chosen':'')} style={s==='XGG'?{opacity:.4}:undefined}><RadioGroupItem value={s} disabled={s==='XGG'} className="sr-only" aria-label={s==='XGG'?'XGG esgotado':s}/>{s}</label>)}</RadioGroup><span className="small muted">XGG esgotado · estoque ilustrativo</span></div></div></div>)}<button type="button" className="btn outline" onClick={()=>setAthletes(a=>[...a,{name:'',email:'',distance:e.distances[0],size:''}])} disabled={athletes.length>=10}><Plus size={17}/>Adicionar outro atleta</button><div className="alert-note"><Info size={18}/>Cada atleta terá sua própria inscrição e histórico. Convites para vincular contas serão ativados com a integração de acesso.</div><button type="submit" className="btn primary">Continuar para ofertas <ArrowRight size={16}/></button></form>:step===1?<><div className="panel"><span className="eyebrow">Só junto com sua inscrição</span><h2>Um impulso para sua próxima prova</h2><p style={{marginTop:12,fontSize:14}}>Aproveite os preços especiais e conheça as lojas parceiras. A retirada é pessoal, no endereço da loja.</p></div>{products.map(p=><div className="product" key={p.id}><div className="product-art"><Package size={34}/></div><div style={{flex:1}}><h3>{p.name}</h3><p>{p.store} · {p.description}</p><div className="product-price"><del>{money(p.later)}</del>{money(p.price)}</div><p><MapPin size={12} style={{display:'inline'}}/> {p.address}<br/>{p.hours}</p></div><button className={'btn '+(ids.includes(p.id)?'soft':'outline')} onClick={()=>setIds(x=>x.includes(p.id)?x.filter(i=>i!==p.id):[...x,p.id])}>{ids.includes(p.id)?<><Check size={15}/>Adicionado</>:<><Plus size={15}/>Adicionar</>}</button></div>)}<div className="row between"><button className="btn outline" onClick={()=>setStep(0)}>Voltar</button><button className="btn primary" onClick={()=>setStep(2)}>{ids.length?'Continuar':'Continuar só com a inscrição'}<ArrowRight size={16}/></button></div></>:<><div className="panel stack"><h2 style={{fontSize:25}}>Como você prefere pagar?</h2><RadioGroup value={payment} onValueChange={setPayment} className="stack">{[{v:'pix',name:'Pix',sub:'Taxa de administração menor'},{v:'card',name:'Cartão à vista',sub:'Uma única parcela'},{v:'installments',name:'Cartão parcelado',sub:'Até '+state.settings.maxInstallments+' vezes'}].map(o=><label key={o.v} className={'choice row '+(payment===o.v?'chosen':'')}><RadioGroupItem value={o.v}/><div><strong>{o.name}</strong><div className="small muted">{o.sub}</div></div></label>)}</RadioGroup>{payment==='installments'&&<Picker label="Parcelas" value={parcels} onChange={setParcels} items={Array.from({length:Math.max(1,state.settings.maxInstallments-1)},(_,i)=>({value:String(i+2),label:`${i+2}x de aproximadamente ${money(total/(i+2))}`}))}/>}<div className="alert-note"><LockKeyhole size={18}/>Pagamento ainda não conectado. Esta etapa salva apenas uma simulação e não solicita dados de cartão.</div><label className="row" style={{fontSize:13,alignItems:'start'}}><Checkbox checked={terms} onCheckedChange={v=>setTerms(v===true)} aria-label="Aceitar condições"/><span>Li as condições de retirada e cancelamento. Entendo que este pedido é demonstrativo e não garante vaga em um evento real.</span></label><div className="row between"><button className="btn outline" onClick={()=>setStep(1)}>Voltar</button><button className="btn primary" disabled={busy||!terms} onClick={finish}>{busy?'Salvando…':'Concluir simulação'}<ArrowRight size={16}/></button></div></div></>}</div><aside className="panel booking-box"><h3>Resumo da inscrição</h3><img src={e.image} alt="Imagem ilustrativa da corrida" style={{width:'100%',height:120,borderRadius:8,marginBottom:15}}/><strong>{e.name}</strong><p className="small muted">{dateLabel(e.date)} · {e.city}</p><div className="rule"/>{athletes.map((a,i)=><div className="summary-line" key={i}><span>Atleta {i+1} · {a.distance} km {a.size&&'· '+a.size}</span><span>{money(racePrice(e,a.distance))}</span></div>)}<div className="summary-line"><span>Taxa de administração</span><span>{money(fee)}</span></div>{ids.map(id=><div className="summary-line" key={id}><span>{products.find(p=>p.id===id)!.name}</span><span>{money(products.find(p=>p.id===id)!.price)}</span></div>)}<div className="summary-line summary-total"><span>Total</span><span>{money(total)}</span></div><p className="small muted">{payment==='pix'?'No Pix':payment==='card'?'No cartão à vista':'No cartão parcelado'} · valores de demonstração</p></aside></div></main>
}
function AthleteDashboard({state,mutate,busy,loading}:{state:Workspace;mutate:Mutation;busy:boolean;loading:boolean}){
 const [add,setAdd]=useState(false),[distance,setDistance]=useState('5'),[official,setOfficial]=useState(false),[form,setForm]=useState({name:'',date:'',city:'',distance:'5',hours:'0',minutes:'0',seconds:'0',millis:'0',link:''});
 const samples=state.results.length===0;const all=samples?initialResults:state.results;const filtered=all.filter(r=>r.distance===Number(distance)&&(!official||r.source==='Oficial')).sort((a,b)=>a.date.localeCompare(b.date));const best=filtered.length?Math.min(...filtered.map(r=>r.ms)):0;const gain=filtered.length>1?filtered[0].ms-filtered[filtered.length-1].ms:0;const next=state.orders.find(o=>!o.cancelRequested);const upcoming=events.find(e=>e.id===next?.eventId)||events[0];
 async function save(ev:FormEvent){ev.preventDefault();const ms=Number(form.hours)*3600000+Number(form.minutes)*60000+Number(form.seconds)*1000+Number(form.millis);if(ms<=0){toast.error('Informe um tempo maior que zero.');return}const r=await mutate('result',{name:form.name,date:form.date,city:form.city,distance:Number(form.distance),ms,link:form.link});if(r){setAdd(false);setDistance(form.distance);toast.success('Corrida adicionada à sua jornada.')}}
 return <main className="wrap page-pad"><div className="title-row"><div><span className="eyebrow">Sua história em movimento</span><h1>Minha jornada</h1><p>Cada largada conta. Cada conquista é sua.</p></div><div className="row no-print"><button className="btn outline" onClick={()=>window.print()}><Download size={16}/>Relatório</button><button className="btn primary" onClick={()=>setAdd(true)}><Plus size={16}/>Adicionar corrida</button></div></div><Tabs defaultValue="evolucao"><TabsList className="bg-transparent p-0 gap-5 border-b rounded-none w-full justify-start h-12 mb-2"><TabsTrigger value="evolucao" className="rounded-none border-b-2 border-transparent data-[state=active]:border-emerald-700 data-[state=active]:shadow-none bg-transparent">Minha evolução</TabsTrigger><TabsTrigger value="historico" className="rounded-none border-b-2 border-transparent data-[state=active]:border-emerald-700 data-[state=active]:shadow-none">Histórico de provas</TabsTrigger></TabsList><TabsContent value="evolucao">{samples&&<div className="row small muted" style={{marginTop:15}}><Info size={14}/>Visualização com resultados de exemplo. Adicione sua primeira corrida para começar seu histórico.</div>}<div className="stats"><Stat label="Provas concluídas" value={String(all.length)} note={samples?'Dados ilustrativos':'Seu histórico pessoal'} icon={Flag}/><Stat label="Quilômetros em provas" value={String(all.reduce((s,r)=>s+r.distance,0))+' km'} note="Cada quilômetro conta" icon={Footprints}/><Stat label={'Melhor tempo · '+distance+' km'} value={best?timeLabel(best).slice(3,8):'—'} note={best?'Seu recorde nesta distância':'Adicione um resultado'} icon={Trophy}/><Stat label="Ritmo do melhor tempo" value={best?pace(best,Number(distance)):'—'} note="min/km" icon={Activity}/></div><div className="dash-grid"><section className="panel"><div className="row between"><div><h3 style={{marginBottom:6}}>Você está indo mais longe</h3><p className="metric-sub">Tempo de prova · menor é melhor</p></div><div style={{width:85}}><Picker value={distance} label="Distância do gráfico" onChange={setDistance} items={[...new Set([5,7,10,15,21,42,...all.map(r=>r.distance)])].sort((a,b)=>a-b).map(d=>({value:String(d),label:d+' km'}))}/></div></div>{filtered.length?<><div className="chart-area"><ResponsiveContainer width="100%" height="100%"><LineChart data={filtered.map(r=>({name:new Date(r.date+'T12:00:00').toLocaleDateString('pt-BR',{month:'short',day:'2-digit'}),tempo:r.ms/60000,title:r.name}))} margin={{left:0,right:20,top:15,bottom:5}}><CartesianGrid strokeDasharray="4 5" vertical={false} stroke="#e6eef0"/><XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize:12,fill:'#7d909b'}} dy={10}/><YAxis domain={['auto','auto']} axisLine={false} tickLine={false} tick={{fontSize:12,fill:'#7d909b'}} width={42} tickFormatter={v=>Math.round(v)+'′'}/><Tooltip formatter={v=>[timeLabel(Math.round(Number(v)*60000)),'Tempo']} contentStyle={{borderRadius:10,border:'1px solid #dfe8eb'}}/><Line type="monotone" dataKey="tempo" stroke="#238c73" strokeWidth={3} dot={{r:5,fill:'#fff',strokeWidth:3}} activeDot={{r:7}}/></LineChart></ResponsiveContainer></div><div className="row between" style={{marginTop:20}}><span className="badge">{gain>0?'Melhora de '+timeLabel(gain).slice(3,8):'Sua evolução, prova a prova'}</span><span className="small muted">{filtered.length} provas de {distance} km</span></div></>:<Empty title="Sua próxima marca começa aqui" text="Nenhum tempo registrado para esta distância."/>}</section><div className="stack"><section className="next-event"><img src={upcoming.image} alt="Imagem ilustrativa da próxima corrida"/><div><span className="tag">{next?'Sua próxima corrida':'Seu próximo desafio?'}</span><h2>{upcoming.name}</h2><p>{dateLabel(upcoming.date)} · {upcoming.city}</p><div className="row"><BtnLink kind="green" href={next?'/ingressos':'/evento/'+upcoming.id}>{next?'Ver inscrição':'Conhecer a prova'}<ArrowRight size={15}/></BtnLink></div></div></section><div className="panel"><div className="row"><Trophy color="#b99742" size={28}/><div><strong>Seu melhor adversário é você.</strong><p className="small muted" style={{marginTop:5}}>Compare provas da mesma distância. Percurso e clima também fazem diferença.</p></div></div></div></div></div></TabsContent><TabsContent value="historico"><div className="alert-note" style={{marginTop:20}}><Info size={18}/>{samples?'Resultados ilustrativos. Seu histórico real começa ao adicionar uma corrida.':'Resultados pessoais informados por você. Integração com cronometragem ainda não conectada.'}</div></TabsContent></Tabs><section className="panel" style={{marginTop:24}}><div className="row between" style={{flexWrap:'wrap'}}><div><h3 style={{marginBottom:7}}>Cada corrida, uma conquista</h3><p className="small muted">Resultados da plataforma e de outras provas, no mesmo lugar.</p></div><label className="row small muted"><Switch checked={official} onCheckedChange={setOfficial}/>Somente oficiais</label></div><div className="table-scroll"><Table className="result-table"><TableHeader><TableRow><TableHead>Corrida</TableHead><TableHead>Data</TableHead><TableHead>Distância</TableHead><TableHead>Tempo líquido</TableHead><TableHead>Ritmo</TableHead><TableHead>Origem</TableHead></TableRow></TableHeader><TableBody>{all.filter(r=>!official||r.source==='Oficial').sort((a,b)=>b.date.localeCompare(a.date)).map(r=><TableRow key={r.id}><TableCell><strong>{r.name}</strong>{r.link&&<a href={r.link} target="_blank" rel="noopener noreferrer" aria-label="Ver resultado" style={{marginLeft:8,display:'inline-flex'}}><ExternalLink size={13}/></a>}</TableCell><TableCell>{dateLabel(r.date)}</TableCell><TableCell>{r.distance} km</TableCell><TableCell>{timeLabel(r.ms)}</TableCell><TableCell>{pace(r.ms,r.distance)}/km</TableCell><TableCell><span className={'badge '+(r.source!=='Oficial'?'gray':'')}>{r.source}</span></TableCell></TableRow>)}</TableBody></Table></div>{official&&<p className="muted" style={{padding:20}}>Nenhum resultado oficial importado.</p>}</section><Dialog open={add} onOpenChange={setAdd}><DialogContent className="modal sm:max-w-xl"><DialogTitle>Mais uma corrida na sua história</DialogTitle><DialogDescription>Inclua também provas realizadas fora da VIVA.</DialogDescription><form onSubmit={save} className="stack"><Field label="Nome da corrida"><input required value={form.name} onChange={e=>setForm({...form,name:e.target.value})} placeholder="Qual foi a prova?"/></Field><div className="form-grid"><Field label="Data da prova"><input required type="date" max={new Date().toISOString().slice(0,10)} value={form.date} onChange={e=>setForm({...form,date:e.target.value})}/></Field><Field label="Distância em km"><input required type="number" min="0.1" max="500" step="0.01" value={form.distance} onChange={e=>setForm({...form,distance:e.target.value})}/></Field><Field label="Cidade"><input value={form.city} onChange={e=>setForm({...form,city:e.target.value})}/></Field><Field label="Link da cronometragem opcional"><input type="url" placeholder="https://" value={form.link} onChange={e=>setForm({...form,link:e.target.value})}/></Field></div><div className="row">{[{k:'hours',l:'Horas',max:167},{k:'minutes',l:'Minutos',max:59},{k:'seconds',l:'Segundos',max:59},{k:'millis',l:'Milissegundos',max:999}].map(f=><Field key={f.k} label={f.l}><input required type="number" min="0" max={f.max} value={(form as any)[f.k]} onChange={e=>setForm({...form,[f.k]:e.target.value})}/></Field>)}</div><p className="small muted">O resultado será identificado como “Informado pelo atleta”.</p><button disabled={busy} className="btn primary" type="submit">{busy?'Salvando…':'Salvar corrida'}</button></form></DialogContent></Dialog></main>
}
function Stat({label,value,note,icon:Icon}:{label:string;value:string;note:string;icon:any}){return <div className="stat"><span className="stat-icon"><Icon size={18}/></span><label>{label}</label><strong>{value}</strong><small>{note}</small></div>}
function Tickets({state,mutate,busy}:{state:Workspace;mutate:Mutation;busy:boolean}){const [selected,setSelected]=useState<(Order & {athleteIndex:number})|null>(null),[cancel,setCancel]=useState<Order|null>(null),[info,setInfo]=useState('');return <main className="wrap page-pad"><div className="title-row"><div><span className="eyebrow">Tudo pronto para a largada</span><h1>Minhas inscrições</h1><p>Inscrições, compras e retiradas em um só lugar.</p></div><BtnLink href="/" kind="outline">Encontrar outra corrida <ArrowRight size={16}/></BtnLink></div>{!state.orders.length?<Empty title="Sua próxima história está esperando" text="Você ainda não tem inscrições. Explore as corridas e simule sua primeira compra."><BtnLink href="/">Explorar eventos</BtnLink></Empty>:<div className="stack">{state.orders.map(o=>{const e=events.find(e=>e.id===o.eventId)!;return <article className="panel" key={o.id}><div className="row between" style={{flexWrap:'wrap'}}><div><span className="badge gray">{o.status}</span><h2 style={{fontSize:24,marginTop:13}}>{e.name}</h2><p className="small muted" style={{marginTop:8}}>{dateLabel(e.date)} · {e.city} · Pedido {o.id.slice(0,8).toUpperCase()}</p></div><strong style={{fontSize:23}}>{money(o.total)}</strong></div><div className="rule"/>{o.athletes.map((a,i)=><div className="receipt" key={i} style={{marginBottom:12}}><div className="row"><div className="avatar">{a.name.slice(0,2).toUpperCase()}</div><div><h3>{a.name}</h3><p className="small muted">{a.distance} km · camiseta {a.size} · {a.email}</p></div></div><button className="btn outline" disabled={o.cancelRequested} onClick={()=>setSelected({...o,athleteIndex:i})}><Ticket size={16}/>Ver retirada</button></div>)}{o.productIds.length>0&&<div className="alert-note"><Store size={18}/><div>Produtos: {o.productIds.map(id=>products.find(p=>p.id===id)?.name).join(', ')}<br/>Retirada pessoal na loja. {o.delivered?'Entrega demonstrativa registrada.':'Aguardando retirada.'}<br/><button className="btn text" onClick={()=>setSelected({...o,athleteIndex:-1})}>Ver QR Code da loja</button></div></div>}<div className="row" style={{marginTop:17,flexWrap:'wrap'}}><button className="btn text" onClick={()=>setInfo('A transferência de titularidade será permitida até 24 horas antes do evento, mantendo distância e camiseta. A vinculação segura entre contas será ativada na próxima etapa de acesso.')}>Transferir titularidade</button><span style={{color:'#ccd6db'}}>·</span><button className="btn text" onClick={()=>setInfo('A autorização permitirá que outro usuário retire kit e camiseta, com identificação na conta dele. Produtos das lojas não podem ser retirados por terceiros. A vinculação entre contas ainda não está ativa.')}>Autorizar retirada do kit</button><span style={{color:'#ccd6db'}}>·</span><button className="btn text" disabled={o.cancelRequested} onClick={()=>setCancel(o)}>Solicitar cancelamento</button></div></article>})}</div>}<Dialog open={!!selected} onOpenChange={v=>!v&&setSelected(null)}><DialogContent className="modal"><DialogTitle>Retirada demonstrativa</DialogTitle><DialogDescription>Este código não é válido para um evento real.</DialogDescription>{selected&&<><div className="ticket-code"><QRCodeImage value={selected.id+':'+selected.athleteIndex}/><strong>{selected.athleteIndex<0?'Produtos da loja':selected.athletes[selected.athleteIndex].name}</strong><code>{selected.id+':'+selected.athleteIndex}</code><button className="btn text" onClick={async()=>{try{await navigator.clipboard.writeText(selected.id+':'+selected.athleteIndex);toast.success('Código copiado.')}catch{toast.error('Selecione e copie o código acima.')}}}><Copy size={15}/>Copiar código de teste</button></div><div className="summary-line"><span>Camiseta</span><span>{selected.deliveries?.[selected.athleteIndex]?.shirt?'Entregue':'Pendente'}</span></div><div className="summary-line"><span>Demais itens do kit</span><span>{selected.deliveries?.[selected.athleteIndex]?.kit?'Entregues':'Pendentes'}</span></div><div className="alert-note"><Info size={18}/>QR Code individual de teste. Use no painel de entregas para conferir e confirmar cada item separadamente.</div></>}</DialogContent></Dialog><Dialog open={!!info} onOpenChange={v=>!v&&setInfo('')}><DialogContent><DialogTitle>Vinculação entre atletas</DialogTitle><DialogDescription>{info}</DialogDescription></DialogContent></Dialog><Dialog open={!!cancel} onOpenChange={v=>!v&&setCancel(null)}><DialogContent><DialogTitle>Solicitar cancelamento</DialogTitle><DialogDescription>Na compra real, serão respeitados o direito de arrependimento e as demais hipóteses do CDC. Esta solicitação apenas altera o pedido demonstrativo; nenhum estorno financeiro será executado.</DialogDescription><button className="btn primary" disabled={busy} onClick={async()=>{const r=await mutate('cancel',{id:cancel?.id});if(r){setCancel(null);toast.success('Solicitação registrada no pedido.')}}}>Registrar solicitação de teste</button></DialogContent></Dialog></main>}
function Management({path,state,mutate,busy}:{path:string;state:Workspace;mutate:Mutation;busy:boolean}){
 const type=path.startsWith('/admin')?'admin':path.startsWith('/loja')?'loja':'gestao';const root='/'+type;const section=path.split('/')[2]||'visao';const title=type==='admin'?'Administração VIBE':type==='loja'?'Minha loja':'Meu evento';const [settings,setSettings]=useState<Settings>(state.settings),[invite,setInvite]=useState(false),[inviteForm,setInviteForm]=useState({name:'',email:'',role:type==='gestao'?'Equipe':'Lojista'}),[code,setCode]=useState(''),[found,setFound]=useState(''),[foundIndex,setFoundIndex]=useState(0);
 useEffect(()=>setSettings(state.settings),[state.settings]);const total=state.orders.filter(o=>!o.cancelRequested).reduce((s,o)=>s+o.total,0),fees=state.orders.filter(o=>!o.cancelRequested).reduce((s,o)=>s+o.fee,0),sold=state.orders.reduce((s,o)=>s+o.athletes.length,0);const storeGross=state.orders.filter(o=>!o.cancelRequested).reduce((s,o)=>s+o.productIds.reduce((v,id)=>v+(products.find(p=>p.id===id)?.price||0),0),0);const foundOrder=state.orders.find(o=>o.id===found);const nav=[{slug:'visao',name:'Visão geral',icon:LayoutDashboard},...(type==='gestao'?[{slug:'evento',name:'Dados do evento',icon:Flag},{slug:'lotes',name:'Lotes e distâncias',icon:Footprints},{slug:'camisetas',name:'Camisetas e estoque',icon:Shirt},{slug:'kit',name:'Kit da corrida',icon:Package},{slug:'lojas',name:'Lojas parceiras',icon:Store}]:type==='loja'?[{slug:'produtos',name:'Produtos e ofertas',icon:Package}]:[{slug:'eventos',name:'Eventos',icon:CalendarDays},{slug:'parceiros',name:'Parceiros',icon:Store}]),{slug:'pedidos',name:type==='loja'?'Pedidos':'Inscrições',icon:Ticket},{slug:'entregas',name:'Entregas',icon:ScanLine},{slug:'financeiro',name:'Financeiro',icon:Wallet},{slug:'configuracoes',name:type==='loja'?'Dados da loja':'Configurações',icon:SettingsIcon},{slug:'equipe',name:type==='admin'?'Convites e acessos':'Equipe',icon:Users}];
 async function saveSettings(ev:FormEvent){ev.preventDefault();if(await mutate('settings',settings))toast.success('Configurações da prévia salvas.')}
 return <main className="wrap page-pad"><SidebarProvider className="management" style={{minHeight:0}}><Sidebar collapsible="none" className="management-nav" aria-label="Gestão"><label>{title}</label><SidebarMenu>{nav.map(n=><SidebarMenuItem key={n.slug}><SidebarMenuButton asChild isActive={section===n.slug}><Link href={n.slug==='visao'?root:root+'/'+n.slug} className={section===n.slug?'active':''}><n.icon size={18}/>{n.name}</Link></SidebarMenuButton></SidebarMenuItem>)}</SidebarMenu><label>Explorar perfis da prévia</label><Link href="/admin">Dono do SaaS</Link><Link href="/gestao">Organizador</Link><Link href="/loja">Lojista</Link></Sidebar><div className="management-main"><div className="title-row"><div><span className="eyebrow">{type==='admin'?'Gestão da plataforma':type==='loja'?'Ponto do Atleta':'Meia Maratona da Orla'}</span><h1>{nav.find(n=>n.slug===section)?.name||title}</h1><p>{type==='admin'?'Eventos, parceiros e condições comerciais.':type==='loja'?'Sua loja mais perto de quem corre.':'Tudo o que sua corrida precisa, em um lugar.'}</p></div><span className="tag">Painel demonstrativo</span></div>
 {section==='visao'?<><div className="stats" style={{gridTemplateColumns:'repeat(3,1fr)'}}><Stat label={type==='loja'?'Vendas de produtos':'Inscrições simuladas'} value={type==='loja'?money(storeGross):String(sold)} note="Pedidos desta prévia" icon={Ticket}/><Stat label="Valor bruto" value={money(type==='loja'?storeGross:total)} note="Nenhum pagamento real" icon={Wallet}/><Stat label={type==='loja'?'Líquido estimado':'Taxas de administração'} value={money(type==='loja'?storeGross*(1-settings.storeCost/100):fees)} note={type==='loja'?'Após custos financeiros':'Configuração negociável'} icon={TrendingUp}/></div>{type!=='loja'&&<div className="commission"><div className="row"><CheckCircle2 size={24}/><strong>{settings.stores?'Setup isento para este evento':'Setup do evento: '+money(settings.setup)}</strong></div><p>{settings.stores?'Lojinhas autorizadas. Economia de '+money(settings.setup)+' para o organizador.':'Autorize a participação de lojinhas para obter a isenção.'}</p></div>}<section className="panel"><div className="row between"><h3>{type==='loja'?'Suas ofertas no evento':'Evento em destaque'}</h3><BtnLink href={root+'/configuracoes'} kind="text">Configurar <ArrowRight size={15}/></BtnLink></div>{type==='loja'?<div className="stack">{products.map(p=><div className="receipt" key={p.id}><div><h3>{p.name}</h3><p className="small muted">Junto da inscrição: {money(p.price)} · Depois: {money(p.later)}</p></div><span className="badge gray">{p.stock} em estoque ilustrativo</span></div>)}</div>:<><img src={events[0].image} alt="Corrida ilustrativa" style={{width:'100%',height:170,borderRadius:9,marginBottom:20}}/><div className="row between"><div><h2 style={{fontSize:24}}>Meia Maratona da Orla</h2><p className="small muted" style={{marginTop:8}}>15 nov 2026 · Florianópolis · 5, 10 e 21 km</p></div><BtnLink href="/evento/orla" kind="outline">Ver página</BtnLink></div></>}</section><div className="alert-note" style={{marginTop:20}}><Info size={18}/>Os perfis desta prévia compartilham o seu ambiente privado de teste. A liberação real de organizadores, lojistas e funcionários será feita com contas e permissões individuais.</div></>:
 ['evento','lotes','camisetas','kit','lojas','produtos','eventos','parceiros'].includes(section)?<ManagementPage key={section} section={section as 'evento'|'lotes'|'camisetas'|'kit'|'lojas'|'produtos'|'eventos'|'parceiros'}/>:section==='configuracoes'?<form className="stack" onSubmit={saveSettings}>{type==='loja'?<section className="panel stack"><h3>Apresente sua loja aos atletas</h3><div className="form-grid"><Field label="Nome da empresa"><input required value={settings.storeName} onChange={e=>setSettings({...settings,storeName:e.target.value})}/></Field><Field label="Telefone ou WhatsApp"><input value={settings.storePhone} onChange={e=>setSettings({...settings,storePhone:e.target.value})} placeholder="(00) 00000-0000"/></Field><div className="wide"><Field label="Endereço de retirada"><input required value={settings.storeAddress} onChange={e=>setSettings({...settings,storeAddress:e.target.value})}/></Field></div><div className="wide"><Field label="Dias e horários de retirada"><textarea required value={settings.storeHours} onChange={e=>setSettings({...settings,storeHours:e.target.value})}/></Field></div></div><div className="alert-note"><Info size={18}/>A foto da fachada e o cadastro completo de produtos serão conectados ao envio de arquivos na próxima etapa.</div></section>:<><section className="panel"><h3>Participação das lojas</h3><div className="row between"><div><strong>Autorizar lojinhas neste evento</strong><p className="small muted">A autorização isenta o setup.</p></div><Switch checked={settings.stores} onCheckedChange={v=>setSettings({...settings,stores:v})} aria-label="Autorizar lojinhas"/></div><div className="form-grid" style={{marginTop:22}}><Field label="Setup do evento em R$"><input type="number" min="0" step="0.01" value={settings.setup} onChange={e=>setSettings({...settings,setup:Number(e.target.value)})}/></Field><Field label="Aluguel da loja em R$"><input type="number" min="0" step="0.01" value={settings.rent} onChange={e=>setSettings({...settings,rent:Number(e.target.value)})}/></Field></div><div className="commission" style={{marginBottom:0}}>Setup a cobrar: <strong>{money(settings.stores?0:settings.setup)}</strong></div></section><section className="panel stack"><h3>Primeiro lote da corrida</h3><div className="form-grid"><Field label="Quantidade de vagas"><input type="number" min="1" value={settings.lotQuantity} onChange={e=>setSettings({...settings,lotQuantity:Number(e.target.value)})}/></Field><Field label="Encerramento ou prorrogação"><input type="date" required value={settings.lotEnd} onChange={e=>setSettings({...settings,lotEnd:e.target.value})}/></Field></div><p className="small muted">A virada ocorre pelo primeiro limite atingido: data ou quantidade. Nesta prévia, a configuração é salva; a automação de estoque e virada será ligada às vendas reais.</p></section></>}<button type="submit" className="btn primary" disabled={busy}>{busy?'Salvando…':'Salvar configurações'}</button></form>:
 section==='financeiro'?<div className="stack"><section className="panel"><h3>{type==='loja'?'Custos e repasses':'Condições financeiras'}</h3><p className="muted">{type==='loja'?'Todas as despesas financeiras são descontadas da venda. Não há comissão.':'Taxas acrescentadas à inscrição, pagas pelo atleta. Custos do processamento saem da administração.'}</p>{type==='loja'?<><div className="summary-line"><span>Vendas brutas simuladas</span><strong>{money(storeGross)}</strong></div><div className="summary-line"><span>Custos financeiros de exemplo · {settings.storeCost}%</span><strong>− {money(storeGross*settings.storeCost/100)}</strong></div><div className="summary-line summary-total"><span>Líquido estimado</span><strong>{money(storeGross*(1-settings.storeCost/100))}</strong></div></>:<form onSubmit={saveSettings}><div className="alert-note" style={{marginTop:18}}>Conversão abaixo usa uma inscrição de R$ 100 como referência. A base escolhida define se a taxa acompanha o preço.</div>{(['pix','card','installments'] as const).map((key,i)=><div className="rate-row" key={key}><strong>{['Pix','Cartão à vista','Cartão parcelado'][i]}</strong><Picker label={'Base '+key} value={settings[key].mode} onChange={v=>setSettings({...settings,[key]:{...settings[key],mode:v}})} items={[{value:'percent',label:'Percentual (%)'},{value:'fixed',label:'Valor fixo (R$)'}]}/><Field label={settings[key].mode==='percent'?'Taxa em %':'Taxa em R$'}><input type="number" min="0" step="0.01" value={settings[key].value} onChange={e=>setSettings({...settings,[key]:{...settings[key],value:Number(e.target.value)}})}/></Field><div className="muted">{settings[key].mode==='percent'?money(settings[key].value):settings[key].value+'%'}<div className="small">Equivalente sobre R$ 100</div></div></div>)}<div className="form-grid"><Field label="Máximo de parcelas"><input type="number" min="2" max="12" value={settings.maxInstallments} onChange={e=>setSettings({...settings,maxInstallments:Number(e.target.value)})}/></Field><Field label="Custo financeiro da loja em %"><input type="number" min="0" max="100" step="0.01" value={settings.storeCost} onChange={e=>setSettings({...settings,storeCost:Number(e.target.value)})}/></Field></div><button className="btn primary" disabled={busy} style={{marginTop:20}}>Salvar taxas</button></form>}</section><section className="panel"><h3>Quando acontece o repasse?</h3><div className="row"><CalendarDays color="#25866b" size={30}/><div><strong>Até 7 dias corridos</strong><p className="muted">{type==='loja'?'Após a confirmação da entrega ao comprador.':'Após a realização do evento, para o organizador.'}</p></div></div><p className="small muted" style={{marginTop:20}}>Repasses e estornos reais ainda não estão conectados a um provedor de pagamento.</p></section>{type==='loja'&&state.orders.some(o=>o.deliveredAt)&&<section className="panel"><h3>Entregas registradas</h3>{state.orders.filter(o=>o.deliveredAt).map(o=><div className="summary-line" key={o.id}><span>Pedido {o.id.slice(0,8)}</span><span>Prazo demonstrativo: {new Date(new Date(o.deliveredAt!).getTime()+7*86400000).toLocaleDateString('pt-BR')}</span></div>)}</section>}</div>:
 section==='equipe'?<section className="panel"><div className="row between"><h3>{type==='admin'?'Liberação de cadastros':'Pessoas da equipe'}</h3><button className="btn primary" onClick={()=>setInvite(true)}><Plus size={16}/>Preparar convite</button></div><p className="muted" style={{marginBottom:20}}>Cadastre os dados para preparar o acesso. Nenhuma mensagem será enviada nesta prévia.</p>{state.invites.length?<div className="stack">{state.invites.filter(i=>type==='admin'||i.role==='Equipe').map(i=><div className="receipt" key={i.id}><div><h3>{i.name}</h3><p className="small muted">{i.email} · {i.role}</p></div><span className="badge amber">Aguardando integração de acesso</span></div>)}</div>:<Empty title="Sua equipe começa aqui" text="Prepare os dados de quem vai ajudar no evento."/>}</section>:
 section==='entregas'?<div className="stack"><section className="panel stack"><div className="row"><ScanLine size={28} color="#207c63"/><div><h3 style={{margin:0}}>Conferência de retirada</h3><p className="small muted">Consulte primeiro. Confirme somente após entregar.</p></div></div><form className="row" onSubmit={ev=>{ev.preventDefault();const id=code.trim().split(':')[0];if(!state.orders.some(o=>o.id===id))toast.error('Código não encontrado nos seus pedidos de teste.');else{setFound(id);setFoundIndex(Number(code.trim().split(':')[1]??0))}}}><label className="field" style={{flex:1}}>Código do pedido<input value={code} onChange={e=>setCode(e.target.value)} placeholder="Cole o código da inscrição" required/></label><button className="btn primary" style={{marginTop:25}}>Consultar</button></form><CameraScan onCode={value=>{setCode(value);const [id,idx]=value.split(':');if(state.orders.some(o=>o.id===id)){setFound(id);setFoundIndex(Number(idx??0))}else toast.error('Código não encontrado.')}}/></section>{foundOrder&&<section className="panel"><h3>{events.find(e=>e.id===foundOrder.eventId)?.name}</h3><p className="muted">{foundIndex>=0?foundOrder.athletes[foundIndex]?.name+' · '+foundOrder.athletes[foundIndex]?.distance+' km · '+foundOrder.athletes[foundIndex]?.size:'Produtos da loja · retirada pelo comprador'}</p>{foundOrder.cancelRequested|| (type==='loja'?foundIndex!==-1:!foundOrder.athletes[foundIndex])?<div className="error">Retirada bloqueada. Confira o cancelamento e use o QR Code correto: atleta para o kit, loja para os produtos.</div>:<><div className="alert-note" style={{margin:'20px 0'}}>Confirmação apenas demonstrativa. {type==='loja'?'A retirada é pessoal pelo comprador.':'A camiseta e os demais itens têm controles separados.'}</div><div className="stack">{(type==='loja'?['delivered']:['shirtDelivered','kitDelivered']).map(item=><div className="row between" key={item}><strong>{item==='delivered'?'Produtos da loja':item==='shirtDelivered'?'Camiseta':'Demais itens do kit'}</strong><button className="btn outline" disabled={busy||(item==='delivered'?foundOrder.delivered:foundOrder.deliveries?.[foundIndex]?.[item==='shirtDelivered'?'shirt':'kit'])} onClick={async()=>{if(await mutate('delivery',{id:foundOrder.id,item,index:foundIndex}))toast.success('Entrega de teste registrada.')}}>{(item==='delivered'?foundOrder.delivered:foundOrder.deliveries?.[foundIndex]?.[item==='shirtDelivered'?'shirt':'kit'])?'Entregue':'Confirmar entrega'}</button></div>)}</div></>}</section>}</div>:
 <section className="panel"><h3>{type==='loja'?'Pedidos da loja':'Inscrições do evento'}</h3>{!state.orders.length?<Empty title="Nenhum pedido por enquanto" text="Simule uma inscrição para conhecer o fluxo completo."><BtnLink href="/">Explorar corridas</BtnLink></Empty>:<div className="table-scroll"><Table className="result-table"><TableHeader><TableRow><TableHead>Pedido</TableHead><TableHead>Participante</TableHead><TableHead>Valor</TableHead><TableHead>Situação</TableHead></TableRow></TableHeader><TableBody>{state.orders.filter(o=>type!=='loja'||o.productIds.length).map(o=><TableRow key={o.id}><TableCell>{o.id.slice(0,8)}</TableCell><TableCell>{o.athletes.map(a=>a.name).join(', ')}</TableCell><TableCell>{money(type==='loja'?o.productIds.reduce((s,id)=>s+products.find(p=>p.id===id)!.price,0):o.total)}</TableCell><TableCell><span className="badge gray">{o.status}</span></TableCell></TableRow>)}</TableBody></Table></div>}</section>}
 </div></SidebarProvider><Dialog open={invite} onOpenChange={setInvite}><DialogContent><DialogTitle>Preparar acesso</DialogTitle><DialogDescription>Cadastre os dados. O envio e a ativação de convites serão conectados posteriormente.</DialogDescription><form className="stack" onSubmit={async ev=>{ev.preventDefault();if(await mutate('invite',inviteForm)){setInvite(false);toast.success('Dados do convite salvos. Nenhuma mensagem enviada.')}}}><Field label="Nome"><input required value={inviteForm.name} onChange={e=>setInviteForm({...inviteForm,name:e.target.value})}/></Field><Field label="E-mail"><input required type="email" value={inviteForm.email} onChange={e=>setInviteForm({...inviteForm,email:e.target.value})}/></Field>{type==='admin'&&<Picker label="Perfil" value={inviteForm.role} onChange={v=>setInviteForm({...inviteForm,role:v})} items={['Organizador','Lojista','Equipe'].map(r=>({value:r,label:r}))}/>}<button className="btn primary" disabled={busy}>Salvar dados do convite</button></form></DialogContent></Dialog></main>
}

function QRCodeImage({value}:{value:string}){const [src,setSrc]=useState('');useEffect(()=>{let active=true;QRCode.toDataURL(value,{width:250,margin:2,color:{dark:'#103c4c',light:'#ffffff'}}).then(s=>active&&setSrc(s)).catch(()=>toast.error('Não foi possível gerar o QR Code. Use o código escrito.'));return()=>{active=false}},[value]);return src?<img src={src} alt="QR Code de retirada demonstrativa"/>:<p>Gerando QR Code…</p>}
function CameraScan({onCode}:{onCode:(s:string)=>void}){const [active,setActive]=useState(false),[error,setError]=useState('');const video=useRef<HTMLVideoElement>(null);useEffect(()=>{if(!active)return;let stream:MediaStream|null=null;let timer:ReturnType<typeof setTimeout>;let stopped=false;async function start(){try{const Detector=(window as any).BarcodeDetector;if(!Detector)throw new Error('Este navegador não oferece leitura por câmera. Cole o código do pedido acima.');stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});if(stopped){stream.getTracks().forEach(t=>t.stop());return}if(video.current){video.current.srcObject=stream;await video.current.play()}const detector=new Detector({formats:['qr_code']});async function scan(){if(stopped)return;try{if(video.current&&video.current.readyState>=2){const result=await detector.detect(video.current);if(result.length){onCode(result[0].rawValue);setActive(false);return}}}catch{}timer=setTimeout(scan,350)}scan()}catch(e){setError((e as Error).message);setActive(false)}}start();return()=>{stopped=true;clearTimeout(timer);stream?.getTracks().forEach(t=>t.stop())}},[active]);return <div className="stack">{active?<><video ref={video} className="qr-video" playsInline muted/><button className="btn outline" onClick={()=>setActive(false)}>Fechar câmera</button></>:<button className="btn outline" onClick={()=>{setError('');setActive(true)}}><ScanLine size={17}/>Ler QR Code com a câmera</button>}{error&&<p className="small muted">{error}</p>}</div>}
